    "/((?!\\.well-known/workflow/|artifact-lib/|_next/static|_next/image|favicon.ico|sw.js|offline.html|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)",
    { source: "/.well-known/workflow/:path*", has: [{ type: "header", key: "tailscale-funnel-request" }] },
  ],
};
