import { mkdirSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
const repo = "C:/Users/mgsuk/.t3/worktrees/Moneo/t3-50e2011b-1d566935d8773235";
const { Desktop } = await import(`file:///${repo}/scripts/desktop/harness.mjs`);

const exe = path.join(repo, "desktop/release/win-unpacked/Moneo.exe");
const out = process.argv[2];
const app = new Desktop(exe, "video");

async function record(label) {
  const dir = path.join(out, label);
  rmSync(dir, { recursive: true, force: true });
  mkdirSync(dir, { recursive: true });
  const started = Date.now();
  await app.launch();
  const browser = await app.browser();
  let frame = 0, homeAt = 0, setupSeen = false;
  const pages = () => browser.contexts().flatMap(context => context.pages());
  while (Date.now() - started < 240_000) {
    const all = pages();
    const home = all.find(page => /^http:\/\/localhost:\d+\//.test(page.url()));
    const setup = all.find(page => /\/setup\/index\.html$/.test(page.url()));
    let target = setup;
    if (home && !homeAt) {
      const visible = await home.locator("main h1").first().isVisible().catch(() => false);
      if (visible) homeAt = Date.now() - started;
    }
    if (homeAt) target = home;
    if (setup) setupSeen = true;
    if (target) {
      const shot = await target.screenshot({ type: "jpeg", quality: 80 }).catch(() => null);
      if (shot) writeFileSync(path.join(dir, `${String(frame++).padStart(5, "0")}-${Date.now() - started}-${target === home ? "home" : "setup"}.jpg`), shot);
    }
    if (homeAt && Date.now() - started > homeAt + 2500) break;
    await new Promise(resolve => setTimeout(resolve, 60));
  }
  console.log(`${label}: setup window ${setupSeen ? "shown" : "not shown"}, Home heading visible after ${homeAt} ms (from launch), ${frame} frames`);
  await app.quit();
  return homeAt;
}

try {
  const first = await record("first-open");
  const second = await record("reopen");
  const third = await record("reopen-2");
  writeFileSync(path.join(out, "times.json"), JSON.stringify({ first, second, third }));
} finally {
  if (app.child && !app.child.exited) await app.quit().catch(() => {});
}

